import fs from 'node:fs';
import {demoStar} from './diagnose-access-grades.mjs';
import {planComposition} from '../board-composition.js';
import {boardHeight} from '../board-terrain.js';
const root=new URL('../',import.meta.url);
// Instrument an in-memory module copy. Never edit Board owner source files.
let source=fs.readFileSync(new URL('board-economy.js',root),'utf8').replace("import {createJoinVerifier}","import {createJoinVerifier as actualJoinVerifier}").replace(/from '(\.\/[^']+)'/g,(_,p)=>"from '"+new URL(p,root).href+"'");
if(!source.includes("import {containsBoardPoint}"))source="import {containsBoardPoint} from '"+new URL("board-bounds.js",root).href+"';\n"+source;
source+=`
export const diagnosticFailures=[];function createJoinVerifier(config){if(${process.argv.includes('--robust-bounds')})config={...config,contains:containsBoardPoint};const boundsMisses=[];const contains=(x,z)=>{const ok=config.contains(x,z);if(!ok){const miss=Math.min(...BOARD_CELLS.map(cellWorld).map(c=>Math.max(Math.abs(x-c.x)-Math.sqrt(3)*HEX_RADIUS/2,Math.abs(z-c.z)-(HEX_RADIUS-Math.abs(x-c.x)/Math.sqrt(3)))));boundsMisses.push({x,z,miss});}return ok;};const actual=actualJoinVerifier({...config,contains}),flat=actualJoinVerifier({...config,contains,heightAt:()=>0});return (candidate,board)=>{boundsMisses.length=0;const result=actual(candidate,board);if(!result){const flatten=p=>({...p,y:0});const geometryPass=!!flat({...candidate,access:{...candidate.access,a:flatten(candidate.access.a),b:flatten(candidate.access.b)}},board);const flatCandidate={...candidate,access:{...candidate.access,a:flatten(candidate.access.a),b:flatten(candidate.access.b)}};const blockers=geometryPass?[]:config.obstacles.map((o,index)=>({o,index})).filter(({o})=>!actualJoinVerifier({...config,heightAt:()=>0,contains:()=>true,obstacles:[o]})(flatCandidate,board)).slice(0,4);diagnosticFailures.push({signature:candidate.signature,cause:geometryPass?'actual-terrain-grade-or-ground':blockers.length?'obstacle-footprint':'bounds-or-incomplete-inventory',blockers,boundsMisses:[...boundsMisses],a:candidate.access.a,b:candidate.access.b});}return result;};}
`;
const {resolveBoardEconomy,diagnosticFailures}=await import('data:text/javascript;base64,'+Buffer.from(source).toString('base64'));
const index=JSON.parse(fs.readFileSync(new URL('domestic-assets/index.json',root),'utf8')),catalog=JSON.parse(fs.readFileSync(new URL('simulation-assets/catalog.json',root),'utf8')),tree=catalog.find(x=>x.id==='tree-standing'),parts=JSON.parse(fs.readFileSync(new URL(tree.json.replace(/^\//,''),root),'utf8'));let minX=Infinity,maxX=-Infinity,minZ=Infinity,maxZ=-Infinity;for(const part of parts)for(let i=0;i<part.positions.length;i+=3){minX=Math.min(minX,part.positions[i]);maxX=Math.max(maxX,part.positions[i]);minZ=Math.min(minZ,part.positions[i+2]);maxZ=Math.max(maxZ,part.positions[i+2]);}const dims={'tree-standing':{w:(maxX-minX)*2,d:(maxZ-minZ)*2}};
for(const [q,r]of [[0,0],[-2,-4],[-4,3]]){const board=demoStar(q,r),{assembly}=planComposition(board);diagnosticFailures.length=0;const result=resolveBoardEconomy(board,assembly,boardHeight(assembly),index,dims);const counts={};for(const item of diagnosticFailures)counts[item.cause]=(counts[item.cause]||0)+1;console.log(JSON.stringify({q,r,connected:result.report.connectedInstanceIds,rejections:counts,inventoryWarnings:result.accessWarnings.filter(w=>!w.unreachable),examples:[...diagnosticFailures.filter(x=>x.cause==='obstacle-footprint').slice(0,3),...diagnosticFailures.filter(x=>x.cause==='bounds-or-incomplete-inventory').slice(0,3),...diagnosticFailures.filter(x=>x.cause==='actual-terrain-grade-or-ground').slice(0,1)]},null,2));}

